import React from 'react';
import { Link, graphql } from 'gatsby';
import PageProps from '../models/PageProps';
import { media } from '../utils/media';
import rgba from 'polished/lib/color/rgba';
import darken from 'polished/lib/color/darken';
import lighten from 'polished/lib/color/lighten';
import Nav from '../components/Nav';
import Layout from '../components/Layout';
import Wrapper from '../components/Wrapper';
import Article from '../components/Article';
import { Head as SEOHead } from '../components/SEO';
import config from '../../config/site-config';
import * as styles from './Index.module.scss';

export default class IndexPage extends React.Component<PageProps> {
  public render() {
    const { data } = this.props;
    const { edges, totalCount } = data.allMarkdownRemark;
    return (
      <Layout>
        <Wrapper fullWidth={true}>
          <main className={styles.homepage}>
            <div className={styles.gridRow}>
              <div className={styles.homepageContent + ' ' + styles.center}>
                <h1>
                  Hi. I am <br />
                  Jesús Quintana
                </h1>
                <Nav />
              </div>
            </div>
            <div className={styles.gridRow}>
              <div className={styles.homepageContent}>
                <h2>Latest Posts</h2>
                {edges.map((post) => (
                  <Article
                    title={post.node.frontmatter.title}
                    date={post.node.frontmatter.date}
                    excerpt={post.node.excerpt}
                    timeToRead={post.node.timeToRead}
                    slug={post.node.fields.slug}
                    category={post.node.frontmatter.category}
                    key={post.node.fields.slug}
                  />
                ))}
                <p className={'textRight'}>
                  <Link to={'/blog'}>All articles ({totalCount})</Link>
                </p>
              </div>
            </div>
          </main>
        </Wrapper>
      </Layout>
    );
  }
}

export function Head() {
  const personSchema = {
    '@context': 'https://schema.org',
    '@type': 'Person',
    name: 'Jesús Quintana',
    jobTitle: 'Senior Software Engineer',
    worksFor: {
      '@type': 'Organization',
      name: 'Atlassian'
    },
    description: 'Senior Software Engineer at Atlassian with over 10 years of experience in React, JavaScript, and modern web development.',
    url: config.siteUrl,
    sameAs: [
      'https://github.com/marduke182',
      config.userTwitter ? `https://twitter.com/${config.userTwitter}` : null
    ].filter(Boolean),
    address: {
      '@type': 'PostalAddress',
      addressLocality: 'Sydney',
      addressCountry: 'AU'
    },
    alumniOf: {
      '@type': 'Organization',
      name: 'Universidad Experimental Simón Bolívar'
    }
  };

  return (
    <>
      <SEOHead
        title="Jesús Quintana - Senior Software Engineer | Sydney, Australia"
        description="Senior Software Engineer at Atlassian with over 10 years of experience in React, JavaScript, and modern web development. Based in Sydney, Australia."
        image="/assets/bg.png"
      />
      <script type="application/ld+json">{JSON.stringify(personSchema)}</script>
    </>
  );
}

export const IndexQuery = graphql`
  query {
    allMarkdownRemark(sort: { frontmatter: { date: DESC } }, limit: 5) {
      totalCount
      edges {
        node {
          fields {
            slug
          }
          excerpt(pruneLength: 280)
          frontmatter {
            title
            date(formatString: "DD.MM.YYYY")
            category
          }
          timeToRead
        }
      }
    }
  }
`;